css='''\n  .gfc-multi-btn{width:100%;box-sizing:border-box;padding:5px 4px;border-radius:8px;border:1.5px solid #D8DAE0;background:#fff;color:#9CA3AF;text-align:center;font-family:'Baloo 2',sans-serif;font-weight:700;font-size:11.5px;line-height:normal;cursor:pointer;}\n  .gfc-multi-btn.tem-valores{background:#F3E8FF;border-color:#A21CAF;color:#4C1D95;}\n  .gfc-multi-inline{grid-column:1/-1;display:none;background:#fff;border:1.5px solid #A21CAF;border-radius:10px;padding:8px;margin-top:2px;}\n  .gfc-multi-inline.show{display:block;}\n  .gfc-multi-title{font-family:'Baloo 2',sans-serif;font-size:11px;font-weight:800;color:#7E22CE;margin-bottom:6px;}\n  .gfc-multi-options{display:flex;flex-wrap:wrap;gap:5px;justify-content:center;}\n  .gfc-multi-option{min-width:30px;height:30px;padding:0 7px;border-radius:7px;border:1.5px solid #D8DAE0;background:#fff;color:#4C1D95;font-family:'Baloo 2',sans-serif;font-size:9.5px;font-weight:800;}\n  .gfc-multi-option.on{background:#A21CAF;border-color:#A21CAF;color:#fff;}\n'''
if '.gfc-multi-btn{' not in s:s=s.replace('  .gfc-fixas-btn{',css+'  .gfc-fixas-btn{',1)
